urlset:
{{ range where site.AllPages "Kind" "in" (slice "home" "page" "section") }}
{{ $loc := .Permalink }}
{{ $keep := or (findRE "/posts/" $loc) (findRE "/archives/" $loc) (findRE "/about/" $loc) (findRE "/privacy/" $loc) }}
{{ if $keep }}

  {{ $loc }}
  {{ if .IsPage }}{{ .Date.Format "2006-01-02T15:04:05Z07:00" }}{{ end }}
  {{ if .IsTranslated }}
  {{ range .Translations }}

  {{ end }}

  {{ end }}

{{ end }}
{{ end }}
